const sn=(tt,o)=>{const f=Math.floor(tt),xq=tt-f;return (fr(f+o)*(1-xq)+fr(f+1+o)*xq-.5)*2;};
if(S.lastBeat==null||K.beat<S.lastBeat)S.lastBeat=K.beat;
S.lastBeat=K.beat;

const u=Math.min(width,height);
const bt=K.beat*P.speed;
const en=P.energy*(.55+.45*K.intensity);
const kick=K.pulse*.6+A.bass*.85;
const H=md(P.hue,360);
const H2=md(H-120,360);                 // synthwave secondary (cyan when hue is hot-pink)
const syn=P.style==='synthwave', sil=P.style==='silhouette', wire=P.style==='wireframe', riso=P.style==='riso';
const LL=.82+P.limb*.4;
const SS=u*P.scale/720;
const cx=P.x*width, cy=P.y*height;
let RK=1;                               // riso ink (1 or 2)

// ---- resolve move (pose direct, or act program over sections) ----
let mv=P.pose;
if(P.act==='session'){ const s=K.section; mv = s<1?'idle': s<3?'carve': (K.intensity>.82?'aerial':'crouch'); }
else if(P.act==='barrel'){ mv = (md(K.section,2)===1)?'crouch':'carve'; }
if(mv==='cycle'){ const ph=md(bt,16); mv=ph<6?'carve':ph<10?'crouch':ph<12?'aerial':'idle'; }

// ---- carve dynamics ----
const sway=Math.sin(md(bt,2)*Math.PI);                // -1..1 primary weight-carve (2 beats)
const arc4=Math.sin(md(bt,4)*Math.PI*.5);             // slow 4-beat sweep
const m={ tx:0,ty:0,lean:.12,tilt:.08,crouch:.42,armF:0,armB:0,spin:0,headTuck:0,spray:.3,trail:0 };

if(mv==='carve'){
  m.tx = arc4*84*en + sway*26*en;
  m.ty = -Math.abs(sway)*14*en - kick*7*en;
  m.lean = .1 + sway*.5*en;
  m.tilt = .08 + sway*.55*en;
  m.crouch = .46 + kick*.24*en - Math.abs(sway)*.08;
  m.armF = sway*.4; m.armB = sway*.6; m.trail = clp(.5-sway*.6,0,1);
  m.spray = clp(Math.abs(sway)*1.15 + kick*.7, 0, 1.5);
  m.headTuck = .05 + Math.abs(sway)*.1;
} else if(mv==='crouch'){
  m.tx = Math.sin(md(bt,3)*Math.PI*.66)*30*en;
  m.ty = 8*en - kick*5*en;
  m.crouch = .82 + K.swell*.1 - kick*.05;
  m.lean = .34 + Math.sin(md(bt,4)*Math.PI*.5)*.08;
  m.tilt = .04 + sway*.12*en;
  m.headTuck = .34; m.armF = .3; m.armB = .55;
  m.spray = .55 + kick*.9; m.trail = .8;
} else if(mv==='aerial'){
  const air=Math.sin(md(bt,4)*Math.PI*.5);
  m.tx = air*96*en; m.ty = -108*en - Math.abs(air)*46*en - kick*6*en;
  m.spin = air*.6*en + .12;
  m.tilt = m.spin; m.lean = .18 + air*.15;
  m.crouch = .7; m.headTuck = .18; m.armF = .55; m.armB = -.5;
  m.spray = .12;
} else { // idle cruise
  const w=Math.sin(md(bt,2)*Math.PI);
  m.tx = w*16*en; m.ty = -Math.sin(md(bt,1)*Math.PI*2)*4*en - kick*3*en;
  m.crouch = .32 + K.swell*.06; m.lean = .1 + w*.08; m.tilt = .05 + w*.06;
  m.armF = w*.28; m.armB = -w*.28; m.headTuck = .04 + sn(K.t*.4,71)*.05;
  m.spray = .14;
}

// ================= cached synthwave backdrop =================
const bgKey=width+'_'+height+'_'+P.style+'_'+Math.round(H)+'_'+P.seed;
if(!S.bg || S.bgKey!==bgKey){
  S.bgKey=bgKey;
  const g = S.bg = createGraphics(width,height);
  g.colorMode(HSB,360,100,100,100); g.noStroke();
  const cxb=width*.5, hz=height*.56, sr=u*.4;
  if(wire){
    g.background(230,45,7);
