    for(let yy=0;yy<height;yy+=9) for(let xx=(yy%18?4.5:0);xx<width;xx+=9){
      const d=Math.hypot(xx-cxb,yy-hz)/u; g.fill(md(H+8,360),55,90, clp(22-d*30,0,22)); g.ellipse(xx,yy, clp(3.2-d*3,.5,3.2));
    }
    g.noStroke(); g.fill(H2,45,88,20);
    for(let yy=hz;yy<height;yy+=Math.max(5,(yy-hz)/u*40+4)) g.rect(0,yy,width, clp((yy-hz)/u*7,1,6));
  } else {
    g.background(268,58,11);
    const dc=g.drawingContext;
    dc.save(); dc.beginPath(); dc.arc(cxb,hz,sr,0,7); dc.clip();
    for(let yy=hz-sr; yy<hz+sr; yy+=3){ const t=(yy-(hz-sr))/(2*sr); g.fill(md(H+58*t,360), clp(96-t*30,40,100), 100); g.rect(cxb-sr-2,yy,sr*2+4,3.5); }
    g.fill(268,58,11);
    let gap=3; for(let yy=hz+sr*.12; yy<hz+sr; yy+=gap+2){ gap=clp((yy-hz)/sr*15,1,14); g.rect(cxb-sr-2,yy,sr*2+4,gap); }
    dc.restore();
    // sun glow
    for(let r=sr*1.5;r>sr;r-=6){ g.fill(md(H+20,360),80,100, clp(12*(1-(r-sr)/(sr*.5)),0,12)); g.ellipse(cxb,hz,r*2,r*2); }
    // perspective grid + reflection
    g.stroke(H2,70,100,sil?18:40); g.strokeWeight(1.4);
    for(let j=1;j<=9;j++){ const yy=hz+(j*j)*height*.009; if(yy<height) g.line(0,yy,width,yy); }
    for(let i=-10;i<=10;i++) g.line(cxb+i*u*.04,hz, cxb+i*u*.7, height*1.05);
    g.noStroke();
    // water reflection of sun
    for(let yy=hz; yy<hz+sr*.9; yy+=4){ const t=(yy-hz)/(sr*.9); if((Math.floor(yy)%7)<4) g.fill(md(H+40,360),90,100, clp(30*(1-t),0,30)); else g.fill(0,0,0,0); g.rect(cxb-sr*.5*(1-t*.3),yy, sr*(1-t*.3),3); }
  }
}
image(S.bg,0,0);

// ================= paint helpers =================
function paint(h,s,b){
  if(wire){ noFill(); stroke(md(H2+(h-H)*.3,360),55,100,90); strokeWeight(1.4); return; }
  if(sil){ noStroke(); fill(0,0,3,100); return; }
  if(riso){ noStroke(); if(RK===2) fill(H2,60,96,88); else fill(H,68,84,90); return; }
  if(syn){ stroke(h,90,100,96); strokeWeight(2.1); fill(h,72,clp(b*.42,8,46),100); return; }
  noStroke(); fill(h,s,b,100);
}
function seg(x1,y1,x2,y2,w1,w2){
  const dx=x2-x1,dy=y2-y1,l=Math.hypot(dx,dy)||1,nx=-dy/l,ny=dx/l;
  beginShape();
  vertex(x1+nx*w1,y1+ny*w1); vertex(x2+nx*w2,y2+ny*w2);
  vertex(x2-nx*w2,y2-ny*w2); vertex(x1-nx*w1,y1-ny*w1);
  endShape(CLOSE);
  ellipse(x1,y1,w1*2,w1*2); ellipse(x2,y2,w2*2,w2*2);
}
const rotp=(x,y,a)=>[x*Math.cos(a)-y*Math.sin(a), x*Math.sin(a)+y*Math.cos(a)];

// ================= figure geometry =================
function figGeom(m){
  push();
  translate(cx + m.tx*SS, cy + m.ty*SS);
  scale(SS);
  rotate(m.spin);

  // board tail location (design units) for spray emit
  const boardCY = 156 - m.crouch*14;
  const bt2 = m.tilt;
  const tail = rotp(-118, -8, bt2); const tailX=6+tail[0], tailY=boardCY+tail[1];
  S.tailX = (cx + m.tx*SS) + (Math.cos(m.spin)*tailX - Math.sin(m.spin)*tailY)*SS;
  S.tailY = (cy + m.ty*SS) + (Math.sin(m.spin)*tailX + Math.cos(m.spin)*tailY)*SS;

  // ---- board ----
  push(); translate(6,boardCY); rotate(bt2);
  paint(H2,80,92);
  ellipse(0,0,250,30);
  if(!wire){ noStroke(); fill(sil?0:md(H,360), sil?0:70, sil?3:100, sil?100:70); ellipse(0,0,250,30); if(!sil&&!riso){ fill(H,60,100,50); rect(-4,-13,8,26,3);} }
  if(syn){ stroke(H2,90,100,95); strokeWeight(2.4); noFill(); ellipse(0,0,250,30); }
  pop();

  // ---- geometry of body ----
  const hipX=6+m.lean*34, hipY=boardCY-(122-m.crouch*58);
  const backFoot=rotp(-64,-8,bt2), frontFoot=rotp(80,-8,bt2);
  const bF=[6+backFoot[0],boardCY+backFoot[1]], fF=[6+frontFoot[0],boardCY+frontFoot[1]];
  const kneeB=[(hipX+bF[0])/2-16,(hipY+bF[1])/2+6];
  const kneeF=[(hipX+fF[0])/2+24,(hipY+fF[1])/2+4];
  const shX=hipX+Math.sin(m.lean)*104, shY=hipY-Math.cos(m.lean)*104;
  const hdX=shX+Math.sin(m.lean+m.headTuck)*40+6, hdY=shY-Math.cos(m.lean+m.headTuck)*40;

  // back leg
  paint(md(H+8,360),60,46); seg(hipX-10,hipY, kneeB[0],kneeB[1], 12*LL,10); seg(kneeB[0],kneeB[1], bF[0],bF[1], 10,7*LL);
  // back arm (trailing, dips toward wave on carve)
  const bAx=shX-10, bAy=shY+6;
  const bElb=[bAx-46-m.armB*18, bAy+34+m.trail*30];
  const bHnd=[bAx-70-m.armB*26, bAy+62+m.trail*54];
  paint(md(H-16,360),55,60); seg(bAx,bAy,bElb[0],bElb[1],8.5*LL,7); seg(bElb[0],bElb[1],bHnd[0],bHnd[1],7,5*LL);
  paint(26,42,90); ellipse(bHnd[0],bHnd[1],11,11);

  // torso (wetsuit)
  paint(H,80,70); seg(hipX,hipY, shX,shY, 21, 16);
  if(!wire && !sil){ noStroke(); fill(md(H+30,360), riso?55:85, riso?96:100, riso?90:80); // chest stripe
    const q=rotp(0,-52,m.lean); rect(hipX+q[0]-4, hipY+q[1], 8, 60, 3); }

  // front leg
  paint(md(H+8,360),60,50); seg(hipX+10,hipY, kneeF[0],kneeF[1], 12*LL,10); seg(kneeF[0],kneeF[1], fF[0],fF[1], 10,7*LL);

  // head
  push(); translate(hdX,hdY); rotate(m.lean+m.headTuck*.5);
  paint(26,40,90); ellipse(0,0,40,44);
  if(!wire && !sil){ noStroke();
    fill(md(H+18,360), riso?50:78, riso?95:96, 96); // hair swoosh
    arc(0,-6,44,42, Math.PI*1.02, Math.PI*2.02, CHORD); rect(10,-12,12,18,4);
    fill(0,0,12,88); const blink=frc(K.t*.14+fr(7))<.045; if(blink) rect(6,-3,9,2.2,1); else ellipse(11,-2,6,7); // eye (facing right)
  }
  if(syn){ stroke(H2,80,100,85); strokeWeight(1.6); noFill(); ellipse(0,0,40,44); }
  pop();

  // front arm (reaching forward-down, balance)
  const fAx=shX+8, fAy=shY+4;
  const fElb=[fAx+52+m.armF*26, fAy+30-m.armF*14];
  const fHnd=[fAx+92+m.armF*40, fAy+52-m.armF*10];
  paint(md(H-16,360),55,64); seg(fAx,fAy,fElb[0],fElb[1],8.5*LL,7); seg(fElb[0],fElb[1],fHnd[0],fHnd[1],7,5*LL);
  paint(26,42,92); ellipse(fHnd[0],fHnd[1],11,11);

  pop();
}

// ---- shadow / glow on water ----
noStroke();
if(!wire){ fill(0,0,0,34); ellipse(cx+m.tx*SS*.7, cy+ (154-m.crouch*14)*SS + m.ty*SS*.3, 210*SS, 24*SS); }

// cheap additive neon bloom behind the rider (few large soft shapes, alpha<=35)
if(syn){ blendMode(ADD); noStroke();
  const gx=cx+m.tx*SS, gy=cy+(-70+m.ty)*SS;
  for(let r=3;r>=1;r--){ fill(H,60,100, 8+r*4); ellipse(gx, gy, 150*SS*r*.7, 190*SS*r*.7); }
  fill(H2,50,100,16); ellipse(gx, gy+40*SS, 120*SS,120*SS);
  blendMode(BLEND);
}

// riso misregistered ghost ink (drawn offset UNDER the main ink)
if(riso){ RK=2; push(); translate(6.5*SS,4*SS); figGeom(m); pop(); RK=1; }

