figGeom(m);

// ---- spray particles from board tail ----
const tx0=S.tailX==null?cx:S.tailX, ty0=S.tailY==null?cy:S.tailY;
const nsp=Math.floor((8+P.density*30)*clp(m.spray,0,1.5));
blendMode(syn?ADD:BLEND); noStroke();
for(let i=0;i<nsp;i++){
  const life=frc(K.t*(.85+fr(i*3)*.7)+fr(i*7+2));
  const ang=-2.0+(fr(i*5+1)-.5)*1.25 - m.tilt*.5;
  const spd=(70+fr(i*11+4)*150)*SS*(.6+en*.6);
  const px=tx0+Math.cos(ang)*spd*life;
  const py=ty0+Math.sin(ang)*spd*life + 260*SS*life*life;
  const sz=(2+fr(i*13)*5)*(1-life*.7)*SS;
  const al=clp((1-life)*72*(syn?.9:1),0,80);
  if(sil) fill(0,0,100,al*.5); else if(riso) fill(H2,45,96,al); else if(wire) fill(H2,50,100,al*.6); else fill(md(H2+fr(i)*30,360),35,100,al);
  ellipse(px,py,sz,sz);
}
// treble mist sparkle
const spk=clp(A.treble*1.4+Math.max(0,K.swell-.7)*.5,0,1);
for(let i=0;i<7;i++){ const a=fr(i*9+5)*6.283+K.t*(.3+fr(i)*.4); const rr=(70+fr(i*7)*90)*SS; const al=(Math.sin(K.t*(2+fr(i)*2)+i)*.5+.5)*(8+40*spk);
  fill(md(H2+fr(i)*40,360),25,100,clp(al,0,50)); const sxx=cx+Math.cos(a)*rr, syy=cy-40*SS+Math.sin(a)*rr*.6; rect(sxx-.8,syy-4*SS,1.6,8*SS,1); rect(sxx-4*SS,syy-.8,8*SS,1.6,1); }
blendMode(BLEND);
